import { DisputeRiskService } from "@/services/disputes-risk"; import { errorResponse, successResponse } from "@/lib/api-utils"; export async function GET(_req:Request,{params}:{params:Promise<{id:string}>}){try{const {id}=await params;const dispute=await DisputeRiskService.getForCurrentVendor(id);return dispute?successResponse(dispute):errorResponse("Dispute not found.",404);}catch{return errorResponse("Forbidden",403);}}